syntax = "proto3";
package pd;
import "google/protobuf/descriptor.proto";
import public "google/protobuf/any.proto";

// file options [50000, 51000)
extend google.protobuf.FileOptions
{
    ProtoFileType file_type = 50000;
    // ProtoGenPolicy file_gen_policy = 50001;
}

/*
 * cli_ 表示客户端专用
 * svr_ 表示服务器专用
 */

// message options [51000, 52000)
extend google.protobuf.MessageOptions
{
    MessageGenPolicy message_gen_policy = 51000;
    string super_field_name = 51001;
    ProtoDataLoader data_loader = 51002;
    string cli_message_sharp_type = 51003;
    bool cli_editor_message = 51004;        // 是否是编辑器消息
    string cli_message_attributes = 51005;  // 消息属性
    bool node_is_action = 51006;            // Node是否是Action
    bool node_is_tick = 51007;              // Node是否Tick
    bool cli_allow_set = 51008;             // 是否运行设置字段
    string cli_index_field_name = 51009;    // 索引字段名
    NodeFlow node_flow = 51010;             // Node流向
    bool serialize_allow_write = 51011;
    string svr_index_field_name = 51014;        // 索引字段名列表，逗号分隔(服务器用)。只能定义当前message内的field，或父类中的field，且需注意继承关系中的message是否包含该同名字段
    bool cli_ignore_preload_type = 51015;       // 是否忽略GenPreloadFunc
    bool finish_type_backtrack = 51016;         // 完成条件是否可回溯
    ConditionOwner condition_owner = 51017;     // Condition逻辑归属
    GraphNodeType node_type = 51018;            // GraphNode类型
    FinishTypeOwner finish_type_owner = 51019;  // finish type所属
    string cli_message_tooltip = 51021;         // C# 类型ToolTip
    ChallengeGoalFinishType challenge_goal_finish_type = 51022;
    bool svr_is_extra_filter_base = 51023;                     // 是否生效服务器额外过滤器(基类)
    bool svr_is_extra_filter_derived = 51024;                  // 是否生效服务器额外过滤器(子类)
    bool svr_is_unordered_map = 51025;                         // 是否是unordered_map类型
    bool cli_editor_hidden = 51026;                            // 在编辑器中隐藏该配置（不可见且不自动创建）
    bool cli_message_support_streaming_serialization = 51027;  // 是否额外支持Streaming序列化
    bool cli_serialize_allow_editor_write = 51028;             // 是否允许Editor下序列化写入
}

// field options [52000, 53000)
extend google.protobuf.FieldOptions
{
    FieldGenPolicy field_gen_policy = 52000;
    // bool is_index = 52001;  // 废弃
    string real_type = 52002;
    string map_key_enum_type = 52003;
    string cli_default_value = 52004;
    string port_param_type = 52005;                          // 指定Node端口的参数类型
    bool cli_hide_in_inspector = 52007;                      // 是否在编辑器中隐藏
    string cli_field_attributes = 52008;                     // 字段属性
    bool port_allow_input = 52009;                           // Node端口是否允许输入参数
    bool is_enum_flags = 52010;                              // 是否是flags类型枚举
    string svr_repeated_to_map_field = 52011;                // 索引字段名，用于将repeated字段在C++中转为map（不支持any、不支持联合索引）,在客户端中被视为cli_repeated_to_map_filed
    SvrDataChecker svr_data_checker = 52012;                 // 服务器用于数值关联检查
    bool cli_ignore_preload_field = 52014;                   // 是否忽略GenPreloadFunc
    bool svr_repeated_to_set = 52015;                        // repeated 转为 C++ std::set，不支持message、any等复杂类型
    string cli_repeated_to_map_field = 52016;                // 索引字段名，用于将repeated字段在C#中转为Dict（不支持any、不支持联合索引），支持多key
    string cli_field_tooltip = 52017;                        // C# 字段ToolTip
    bool svr_is_unsigned_int = 52018;                        // 是否是unsigned int类型
    bool svr_is_unordered_map_field = 52019;                 // 是否是unordered_map类型
    bool composite_empty_satisfy = 52020;                    // 为空时是否满足条件，仅对CompositeConditionConfig类型字段有效
    bool cli_message_streaming_serialize_reference = 52021;  // 是否使用SerializeReference形式序列化
    bool cli_skip_member = 52022;                            // 是否跳过Proto序列化/反序列化
}

// enum options [53000, 54000)
extend google.protobuf.EnumOptions
{
    string cli_enum_sharp_type = 53000;
    bool flags = 53001;
    bool extension = 53002;

syntax = "proto3";
package pd;

import public "UnityType.proto";
import public "ABCType.proto";
import "options_extension.proto";
import "TableItemBase.proto";
import public "enum.proto";
import "AdvConditionConfig.proto";
import public "ChessSkillDescConfig.proto";
import "ChsSkillConfig.proto";
import "ChsManualSkillConfig.proto";
import "ChessGameConfig.proto";
import public "GotoConfig.proto";
option (file_type) = DATA_DEFINE;

message TrainerEquipConfig
{
	uint32 EquipID = 1 [(cli_field_attributes) = "JsonConfigField(typeof(ChsEquipmentConfig))", (field_gen_policy) = FIELD_SERVER];
	uint32 Rank = 2 [(field_gen_policy) = FIELD_SERVER];
}

message TrainerLawConfig
{
	uint32 LawID = 1 [(cli_field_attributes) = "JsonConfigField(typeof(ChsLawConfig))"];
	uint32 Rank = 2;
}

message TrainerBreakLevelUpConfig
{
	uint32 BreakID = 1;
	uint32 LevelUp = 2;
}

message TrainerRankConfig
{
	uint32 Rank = 1 [(field_gen_policy) = FIELD_SERVER];
	repeated TrainerEquipConfig Equipment = 2 [(cli_field_attributes) = "TableListFolder(1, '#ffcf99'),TableObjectFolder('#ffcf99')", (field_gen_policy) = FIELD_SERVER];
	TrainerLawConfig Law = 3 [(cli_field_attributes) = "TableObjectFolder('#ffcf99')"];
	repeated TrainerBreakLevelUpConfig BreakLevelUp = 4;
}

message TrainerRankUpDescConfig
{
	uint32 Rank = 1;
	FText Title = 2;
	SoftObjectPath RankPic = 10 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
}

message TrainerRankUpCost
{
	uint32 Rank = 1 [(field_gen_policy) = FIELD_SERVER];
	repeated ItemData RankUpCost = 2 [(field_gen_policy) = FIELD_SERVER];
}

message TrainerChsConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 ID = 2 [(field_gen_policy) = FIELD_SERVER];
	FText Name = 3;
	int32 Rarity = 4 [(field_gen_policy) = FIELD_SERVER];
	repeated TrainerRankConfig RankList = 5 [(svr_repeated_to_map_field) = "Rank", (cli_repeated_to_map_field) = "Rank", (cli_field_attributes) = "TableDictFolder('0;1;2;3;4;5','#ffcf99'),TableObjectFolder('#ffcf99')", (field_gen_policy) = FIELD_SERVER];
	repeated TrainerRankUpDescConfig RankUpDesc = 6 [(cli_repeated_to_map_field) = "Rank"];
	repeated WwiseBank ChsBankConfigs = 7;
	uint32 UltSkillID = 8 [(cli_field_attributes) = "JsonConfigField(typeof(ChsManualSkillConfig))"];
	uint32 CombinationalTraitID = 9 [(cli_field_attributes) = "JsonConfigField(typeof(ChsTraitConfig))"];

	SoftObjectPath IconPath = 10 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarHead64Path = 11 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarPhotoPath = 12 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];

	SoftObjectPath AvatarCardPath = 13 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarCardBgPath = 14 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];

	SoftObjectPath ListAvatarPath = 15 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];

	SoftObjectPath Poster = 16 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarPhoto512 = 28 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"]; 

	SoftObjectPath PerformanceTimeline = 20 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject), 'Assets/Res/Prefabrication/ChessGame/TrainerPerformance')"];
	SoftObjectPath PerformancePhoto = 21 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	FText PerformanceName = 22;
	uint32 EntityConfigID = 23 [(cli_field_attributes) = "JsonConfigField(typeof(ChsTrainerEntityConfig),false)"];
	TrainerEntityLawData TrainerEntityLawData = 24;

	uint32 AudioConfig = 25 [(cli_field_attributes) = "JsonConfigField(typeof(ChessTrainerAudioConfig),false)"];
	repeated ExclusiveSpriteConfig ExclusiveSprite = 27 [(cli_repeated_to_map_field) = "SpriteConfigID", (svr_repeated_to_map_field) = "SpriteConfigID", (field_gen_policy) = FIELD_SERVER];
}

message TrainerEntityLawData
{
	uint32 TrainerEntityLawID = 1 [(cli_field_attributes) = "JsonConfigField(typeof(ChsLawConfig),false)"];
	uint32 LawRank = 2;
}

message LevelRewardConfig
{
	uint32 Level = 1 [(field_gen_policy) = FIELD_SERVER];
	uint32 RewardID = 2 [(svr_data_checker).ref_target = "RewardConfigMgr(RewardConfig)", (field_gen_policy) = FIELD_SERVER];
}

message ExclusiveSpriteConfig
{
	uint32 SpriteConfigID = 1 [(cli_field_attributes) = "RowKeyReference(typeof(SpriteChsTable), 'ChsID')", (field_gen_policy) = FIELD_SERVER];
}

message TrainerCommonConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 ID = 2 [(field_gen_policy) = FIELD_SERVER];
	uint32 AdvCharacterEntityConfigID = 3 [(cli_field_attributes) = "JsonConfigField(typeof(AdvCharacterEntityConfig))", (field_gen_policy) = FIELD_SERVER];
	FText Name = 5;
	FText Description = 6;
	FText SubDescription = 7;
	repeated TrainerRankUpCost RankUpCost = 8 [(svr_repeated_to_map_field) = "Rank", (cli_repeated_to_map_field) = "Rank", (field_gen_policy) = FIELD_SERVER];
	repeated ItemData RepeatGetReward = 9 [(field_gen_policy) = FIELD_SERVER];
	repeated ItemData RepeatGetMaxReward = 10 [(field_gen_policy) = FIELD_SERVER];
	uint32 RankUpItem = 11 [(field_gen_policy) = FIELD_SERVER];
	bool ComingSoon = 12;
	FText Story = 14;
	uint32 Tag = 15 [(cli_field_attributes) = "RowKeyReference(typeof(TrainerTagTableConfig), 'ID')"];

	SoftObjectPath GachaResultPhoto = 18 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];

	uint32 UIEntityConfig = 21 [(cli_field_attributes) = "JsonConfigField(typeof(UIEntityConfig))"];
	repeated LevelRewardConfig LevelRewardList = 25 [(svr_repeated_to_map_field) = "Level", (cli_repeated_to_map_field) = "Level", (field_gen_policy) = FIELD_SERVER];
	bool ShowEmptyState = 26;
	uint32 FirstGetRewardId = 19 [(svr_data_checker).ref_target_allow_zero = "RewardConfigMgr(RewardConfig)", (field_gen_policy) = FIELD_SERVER];
	uint32 GiftSprite = 20 [(field_gen_policy) = FIELD_SERVER, (svr_data_checker).ref_target_allow_zero = "SpriteConfigMgr(SpriteCommonConfig)"];

	bool IsTemporaryResource = 28; // 非正式立绘（抽卡界面用）
}

message TrainerTraitSkillRankVar
{
	map<uint32, ChsSkillVarOverride> RankVarOverride = 1 [(cli_default_value) = "new ()"];
}

message TrainerChsTableConfig
{
	option (data_loader).load_path = "Table/TrainerChs";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (message_gen_policy) = MIXED;
	option (cli_ignore_preload_type) = true;

	repeated TrainerChsConfig TrainerList = 1 [(svr_repeated_to_map_field) = "ID", (cli_repeated_to_map_field) = "ID", (cli_field_attributes) = "TableElements", (field_gen_policy) = FIELD_SERVER];
}

message TrainerCommonTableConfig
{
	option (data_loader).load_path = "Table/TrainerCommon";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (message_gen_policy) = MIXED;
	option (cli_ignore_preload_type) = true;

	repeated TrainerCommonConfig TrainerList = 1 [(svr_repeated_to_map_field) = "ID", (cli_repeated_to_map_field) = "ID", (cli_field_attributes) = "TableElements", (field_gen_policy) = FIELD_SERVER];
}

message TrialTrainerTableConfig
{
	option (data_loader).load_path = "Table/TrialTrainer";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (message_gen_policy) = MIXED;
	option (cli_ignore_preload_type) = true;

	repeated TrialTrainerConfig TrainerList = 1 [(svr_repeated_to_map_field) = "ID", (cli_repeated_to_map_field) = "ID", (cli_field_attributes) = "TableElements", (field_gen_policy) = FIELD_SERVER];
}

enum ChsUniqueTrainerType
{
	ChsUniqueTrainerType_Normal = 0;
	ChsUniqueTrainerType_Boss = 1;
}

message ChsUniqueTrainerConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 ID = 2;
	uint32 TrainerID = 3 [(cli_field_attributes) = "RowKeyReference(typeof(TrainerChsTableConfig), 'ID')"];
	uint32 Rank = 4;
	bool AutoBreakByLevel = 6;
	repeated TrainerBreakData BreakList = 7 [(cli_field_attributes) = "ShowIf('@this.AutoBreakByLevel == false')"];
	uint32 HardLevelGroup = 8 [(cli_field_attributes) = "RowKeyReference(typeof(ChsTrainerHardLevelTable), 'HardLevelGroup')"];
	map<int32, fixed> Attribute = 9 [(map_key_enum_type) = "EntityAttribute", (cli_field_attributes) = "TableDictFolder('MaxMPBase;InitialMPBase;TrainerActivePowerBase;TrainerPassivePowerBase;MPRegenBase','#487eb0')"];
	ChsUniqueTrainerType TrainerType = 10;
}

message ChsUniqueTrainerTable
{
	option (data_loader).load_path = "Table/ChsUniqueTrainer";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (cli_ignore_preload_type) = true;

	repeated ChsUniqueTrainerConfig UniqueTrainerList = 1 [(svr_repeated_to_map_field) = "ID", (cli_repeated_to_map_field) = "ID", (cli_field_attributes) = "TableElements"];
}

message ChsTrainerHardLevelConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 HardLevelGroup = 2;
	uint32 Level = 3;
	map<int32, fixed> AttributeAddendRatio = 4 [(cli_default_value)= "new()", (map_key_enum_type) = "EntityAttribute",(cli_field_attributes) = "TableDictFolder('TrainerActivePowerGrowthAddend;TrainerPassivePowerGrowthAddend')"];
}

message ChsTrainerHardLevelTable
{
	option (data_loader).load_path = "Table/ChsTrainerHardLevel";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (cli_ignore_preload_type) = true;

	repeated ChsTrainerHardLevelConfig HardLevels = 1 [(svr_repeated_to_map_field) = "HardLevelGroup,Level", (cli_repeated_to_map_field) = "HardLevelGroup,Level", (cli_field_attributes) = "TableElements"];
}

message TrialTrainerConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 ID = 2 [(field_gen_policy) = FIELD_SERVER];
	uint32 TrainerID = 3 [(svr_data_checker).ref_target = "TrainerConfigMgr(TrainerCommonConfig)", (field_gen_policy) = FIELD_SERVER];
	uint32 Rank = 4 [(field_gen_policy) = FIELD_SERVER];
	repeated TrainerBreakData BreakList = 5;
	bool IsHideInReward = 6;
	uint32 Level = 7;
	TrialTagType TagType = 8;
}

enum TrialTagType
{
	TrialTagType_Trial = 0;
	TrialTagType_Story = 1;
}

message TrainerTagTableConfig
{
	option (data_loader).load_path = "Table/TrainerTag";
	option (cli_message_attributes) = "TableConfig";
	option (data_loader).is_single_file = true;
	option (cli_ignore_preload_type) = true;

	repeated TrainerTagConfig TagList = 1 [(svr_repeated_to_map_field) = "ID", (cli_repeated_to_map_field) = "ID", (cli_field_attributes) = "TableElements"];
}

message TrainerTagConfig
{
	option (super_field_name) = "Base";
	option (cli_index_field_name) = "ID";
	TableItemBase Base = 1;

	uint32 ID = 2;
	FText TagDesc = 3;
}

message TrainerPageTabItem
{
	TrainerMainPageState TabType = 1;
	FText TabName = 2;
	SoftObjectPath Icon = 3 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	int32 Sort = 4;
	bool ShowInTab = 5;
}

enum TrainerSortType
{
	TrainerSortType_None = 0;
	TrainerSortType_Level = 1;
	TrainerSortType_Rarity = 2;
	TrainerSortType_Rank = 3;
}

message TrainerSortConfig
{
	TrainerSortType SortType = 1;
	bool IsAscent = 2;
	FText SortName = 3;
	bool IsDefault = 4;
}

message TrainerGenderConfig
{
	SoftObjectPath IconPath = 1 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarHead64Path = 2 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarPhotoPath = 3 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarCardPath = 4 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarCardBgPath = 5 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath ListAvatarPath = 6 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath Poster = 7 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath AvatarPhoto512 = 8 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath PerformancePhoto = 9 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.Sprite))"];
	SoftObjectPath PerformanceTimeline = 10 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject), 'Assets/Res/Prefabrication/ChessGame/TrainerPerformance')"];
	uint32 AudioConfig = 11 [(cli_field_attributes) = "JsonConfigField(typeof(ChessTrainerAudioConfig), false)"];
}

message TrainerGlobalConfig
{
	option (data_loader).load_path = "Global/TrainerGlobalConfig";
	option (data_loader).is_single_file = true;

	map<int32, TrainerGenderConfig> GenderConfig = 1 [(map_key_enum_type) = "PlayerGenderType"];

	map<int32, TrainerPageTabItem> Tabs = 10 [(map_key_enum_type) = "TrainerMainPageState"];
	map<int32, FText> TrainerStateTitle = 11 [(map_key_enum_type) = "TrainerMainPageState"];
	repeated TrainerSortConfig TrainerSortConfigs = 12;
	repeated uint32 TrainerBreakCurrencyIDList = 13;
	map<int32, FText> RankTabName = 14;
	repeated FText BreakNodeTitle = 15;

	FText TrainerMainTitle = 24;
	FText TrainerBreakCanNotUnlockForwardNotComplete = 25;
	FText TrainerBreakCanNotUnlockLevelLimit = 26;
	FText TrainerLevelText = 27;
	FText ChangeConfirmDialogTitle = 28;
	FText ChangeConfirmDialogDesc = 29;
	FText CancelChangeConfirmDialogDesc = 30;
	FText NeedWorldLevelHint = 31;
	FText ShowEffectDesc = 32;
	FText AlreadyRankUp = 33;
	FText AlreadyUnlockBreak = 34;
	FText RankUpSuccTipText = 35;
	FText UnlockBreakSuccTipText = 36;
	FText TrainerMinLevel = 37;
	FText TrainerMaxLevel = 38;
	FText TraitSkill = 40;
	FText ActiveSkill = 41;
	FText SimultaneousSkill = 42;
	FText SkillTagFormat = 43;
	FText SpriteNotObtainWithName = 45;
	FText SpriteNotObtain = 46;
	FText SpriteObtained = 47;

	// 3DUI相关
	float BloomThreshold = 60 [(cli_field_attributes) = "Title('3DUI')"];
	float LipShaderNormalPara = 61;
	float LipShaderLevelPara = 62;

	// AttributeFormat相关
	map<int32, AttributeFormat> AttributeFormats = 70 [(map_key_enum_type) = "EntityAttribute", (cli_default_value) = "new ()", (cli_field_attributes) = "Title('AttributeFormat')"];
	map<int32, FText> PassiveEnhanceAttrNameOverride = 71 [(map_key_enum_type) = "EntityAttribute"];
	map<int32, FText> TrainerEnhanceAttrNameOverride = 72 [(map_key_enum_type) = "EntityAttribute"];
	map<int32, FText> SimultaneousEnhanceAttrNameOverride = 73 [(map_key_enum_type) = "EntityAttribute"];

	// TipsAttribute相关
	repeated TipsAttributeGroup AttrbutesTipsMainAttrs = 74 [(cli_field_attributes) = "Title('Tips Attribute')", (cli_field_tooltip) = "属性tips一级属性"];
	repeated TipsAttributeGroup AttrbutesTipsSecondaryAttrs = 75 [(cli_field_tooltip) = "属性tips二级属性"];
	repeated TipsAttributeGroup ActiveSkillTipsAttrs = 76 [(cli_field_tooltip) = "心象页主动技能tips属性"];

	// 局内相关
	fixed SkillSelectingTimeScale = 100 [(cli_field_attributes) = "Title('ChessGame')"];
	SoftObjectPath DragLine = 101 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	fixed TrainerAutoSkillHomeCardAnimationWaitDuration = 102 [(cli_field_tooltip) = "己方卡牌自动技能动画后，进入选择目标预演前的等待时长"];

	fixed TrainerAutoSkillSingleTargetSelectDuration = 110 [(cli_field_attributes) = "Title('TrainerAutoSkillSingleTarget')"];
	SoftObjectPath TrainerAutoSkillSingleTargetHomeIndicator = 111 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillSingleTargetAwayIndicator = 112 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	string TrainerAutoSkillSelectIndicatorSocketName = 113 [(cli_field_tooltip) = "心像大招自动释放时准星加载位置挂点"];

	fixed TrainerAutoSkillGridSelectDuration = 120 [(cli_field_attributes) = "Title('TrainerAutoSkillGrid')"];
	SoftObjectPath TrainerAutoSkillGridHomeIndicator = 121 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillGridAwayIndicator = 122 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];

	fixed TrainerAutoSkillRangeSelectDuration = 130 [(cli_field_attributes) = "Title('TrainerAutoSkillRange')"];
	SoftObjectPath TrainerAutoSkillRange1HomeIndicator = 131 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillRange2HomeIndicator = 132 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillRange3HomeIndicator = 133 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillRange1AwayIndicator = 134 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillRange2AwayIndicator = 135 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillRange3AwayIndicator = 136 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];

	fixed TrainerAutoSkillFullBoardCastSelectDuration = 140 [(cli_field_attributes) = "Title('TrainerAutoSkillFullBoardCast')"];
	SoftObjectPath TrainerAutoSkillFullBoardCastHomeIndicator = 141 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
	SoftObjectPath TrainerAutoSkillFullBoardCastAwayIndicator = 142 [(cli_field_attributes) = "MetaClass(typeof(UnityEngine.GameObject))"];
}

message TrainerBreakData
{
	option (cli_allow_set) = true;
	uint32 BreakID = 1;
	uint32 BreakLevel = 2;
}

enum TrainerBreakEffectBranch
{
	TrainerBreakEffectBranch_Trainer = 0;
	TrainerBreakEffectBranch_Trait = 1;
	TrainerBreakEffectBranch_ExclusiveSprite = 2;
}

message TrainerBreakForwardBreakConfig
{
	uint32 BreakId = 1 [(field_gen_policy) = FIELD_SERVER];
	uint32 Level = 2 [(field_gen_policy) = FIELD_SERVER];
}

message TrainerBreakEffectConfig
{
	uint32 BreakId = 1 [(field_gen_policy) = FIELD_SERVER];
